#include "plugin_state.hpp"
static void processingLifecycleTests(){
    const fs::path module=L"build/processing-fixture.vst3";check(fs::exists(module),"processing lifecycle fixture is built");
    for(auto status:{L"false",L"notimpl",L"ok"}){SetEnvironmentVariableW(L"VAMP_FIXTURE_RESULT",status);Plugin fx;std::string error;if(!fx.load(module,48000,error))throw std::runtime_error("VST lifecycle fixture: "+error);check(fx.prepare(96000),"rate change tolerates nonfatal processing notification status");std::array<float,256>l{},r{};l.fill(.2f);r.fill(-.3f);fx.process(l.data(),r.data(),256,nullptr,0,0,120,true);check(l[128]==.2f&&r[128]==-.3f,"accepted plugin actually processes audio");}
    SetEnvironmentVariableW(L"VAMP_FIXTURE_RESULT",L"error");{Plugin fx;std::string error;check(!fx.load(module,48000,error)&&error.find("processing activation failed")!=std::string::npos,"real processing activation errors remain failures");}SetEnvironmentVariableW(L"VAMP_FIXTURE_RESULT",nullptr);
    {Plugin fx;std::string error;check(fx.load(module,48000,error),"state fixture loads");std::vector<uint8_t>bytes(257);for(size_t i=0;i<bytes.size();i++)bytes[i]=(uint8_t)i;fx.restore(Json{{"component",bytes}});auto compact=fx.state();check(decodePluginStateBytes(compact["component"])==bytes&&compact["component"].is_object(),"real VST restores legacy state and captures compact state");std::fill(bytes.begin(),bytes.end(),73);compact["component"]=encodePluginStateBytes(bytes);fx.restore(Json::parse(compact.dump()));check(decodePluginStateBytes(fx.state()["component"])==bytes,"real VST restores compact state with byte-exact output");}
    for(auto stage:{L"VAMP_FIXTURE_SETUP",L"VAMP_FIXTURE_ACTIVE"}){SetEnvironmentVariableW(stage,L"1");Plugin fx;std::string error;check(!fx.load(module,48000,error),"setupProcessing and setActive failures are never ignored");SetEnvironmentVariableW(stage,nullptr);}
    std::ofstream(L"work/test-results/vst-lifecycle.json")<<Json({{"passed",true},{"nonfatal_statuses",{"ok","false","not_implemented"}},{"process_audio",true},{"prepare_96khz",true},{"real_errors_rejected",true}}).dump(2);
}
